// One place that turns four systems into a page. Each block says what it is
// reading and why, because the shape of these responses is the only
// documentation of them we have.

const esc = (s) => String(s == null ? '' : s)
  .replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
const money = (n) => '£' + Number(n || 0).toFixed(2);
const num = (n) => Number(n || 0).toFixed(2);

const safe = (name, path, fallback) => {
  try {
    let v = $(name).first().json;
    for (const k of path) v = v?.[k];
    return v === undefined || v === null ? fallback : v;
  } catch (e) { return fallback; }
};

// --- bookings -------------------------------------------------------------
const meetings = safe('Bookings', ['list'], []) || [];
const parse = (raw) => {
  if (!raw) return null;
  const iso = String(raw).replace(' ', 'T');
  const d = new Date(iso.endsWith('Z') ? iso : iso + 'Z');
  return isNaN(d) ? null : d;
};
const fmt = (d, opts) => d ? d.toLocaleString('en-GB',
  Object.assign({ timeZone: 'Europe/London' }, opts)) : '';
const now = new Date();
const endOfToday = new Date(now); endOfToday.setHours(23,59,59,999);

const withDate = meetings.map(m => ({ m, d: parse(m.dateStart) })).filter(x => x.d);
const today = withDate.filter(x => x.d >= new Date(now.getTime() - 2*3600*1000) && x.d <= endOfToday)
                      .sort((a,b) => a.d - b.d);
const soon  = withDate.filter(x => x.d > endOfToday).sort((a,b) => a.d - b.d).slice(0, 6);
const joinOf = (m) => (String(m.description || '').match(/Join:\s*(\S+)/) || [])[1] || '';

// Finished jobs nobody has been thanked for yet. Held is set by hand after a
// job, so this list is a by-product of doing the work rather than another
// thing to maintain.
const toThank = withDate
  .filter(x => x.m.status === 'Held' && !x.m.cReviewRequested)
  .sort((a, b) => b.d - a.d)
  .slice(0, 5);

// --- money ----------------------------------------------------------------
const invoices = safe('Invoices', ['Invoices'], []) || [];
const monthStart = new Date(now.getFullYear(), now.getMonth(), 1);
const invDate = (i) => parse((i.DateString || '').slice(0,19)) || parse(i.Date);
const thisMonth = invoices.filter(i => { const d = invDate(i); return d && d >= monthStart; });
const invoiced = thisMonth.reduce((t,i) => t + Number(i.Total || 0), 0);
const paid = thisMonth.reduce((t,i) => t + Number(i.AmountPaid || 0), 0);
const unpaid = invoices.filter(i => i.Status === 'AUTHORISED' && Number(i.AmountDue) > 0);
const owed = unpaid.reduce((t,i) => t + Number(i.AmountDue || 0), 0);

const sum = (arr) => (arr || []).reduce((t,b) => t + (b.amount || 0), 0) / 100;
const available = sum(safe('Stripe balance', ['available'], []));
const pending = sum(safe('Stripe balance', ['pending'], []));
const payout = (safe('Next payout', ['data'], []) || [])[0];

// --- people ---------------------------------------------------------------
const leads = safe('New leads', ['list'], []) || [];
const leadTotal = safe('New leads', ['total'], 0);
const customerTotal = safe('Customers', ['total'], 0);
const newCustomers = safe('Customers', ['list'], []) || [];
const openLeads = leads.filter(l => !['Converted','Dead','Recycled'].includes(l.status));

// --- reviews --------------------------------------------------------------
// A text search can return somebody else entirely, so the name is checked
// before any of this is believed.
const candidates = safe('Google reviews', ['places'], []) || [];
const place = candidates.find(p => /it\s*surgery/i.test(p?.displayName?.text || ''));
const ours = Boolean(place);
const rating = ours ? place?.rating : null;
const ratingCount = ours ? (place?.userRatingCount || 0) : 0;
const reviews = ours ? (place?.reviews || []) : [];

// --- health ---------------------------------------------------------------
const up = (name) => {
  const code = safe(name, ['statusCode'], 0);
  return code >= 200 && code < 400;
};
const deployRun = (safe('Last deploy', ['body','workflow_runs'], []) || [])[0]
               || (safe('Last deploy', ['workflow_runs'], []) || [])[0];
// conclusion is null while a run is still going. That is not a failure, and
// showing red for the thirty seconds after every push trains you to ignore it.
const deployState = !deployRun ? 'unknown'
  : deployRun.status !== 'completed' ? 'running'
  : deployRun.conclusion === 'success' ? 'ok' : 'bad';

// --- rendering ------------------------------------------------------------
const dot = (state) => `<span class="dot ${
  state === true || state === 'ok' ? 'ok' : state === 'running' ? 'busy' : 'bad'}"></span>`;

const leadRows = leads.length ? leads.slice(0,6).map(l => {
  const who = [l.firstName, l.lastName].filter(Boolean).join(' ') || l.name || 'Someone';
  const created = parse(l.createdAt);
  const contact = l.phoneNumber || l.emailAddress || '';
  return `<tr><td>${esc(who)}<div class="sub">${esc(contact)}</div></td>
    <td class="r"><span class="sub">${esc(l.status || '')}</span><div class="sub">${
      created ? esc(fmt(created,{day:'numeric',month:'short'})) : ''}</div></td></tr>`;
}).join('') : '<tr><td colspan="2" class="quiet">No enquiries yet.</td></tr>';

const stars = (r) => r ? '\u2605'.repeat(Math.round(r)) + '\u2606'.repeat(5 - Math.round(r)) : '';

const reviewRows = reviews.length ? reviews.slice(0,3).map(rv => {
  const who = rv.authorAttribution?.displayName || 'Someone';
  const text = (rv.text?.text || rv.originalText?.text || '').slice(0, 180);
  return `<tr><td><span class="stars">${esc(stars(rv.rating))}</span>
    <span class="sub">${esc(who)} \u00b7 ${esc(rv.relativePublishTimeDescription || '')}</span>
    <div>${esc(text)}</div></td></tr>`;
}).join('') : `<tr><td>
    <div class="quiet">${ratingCount ? 'Reviews are on Google.'
      : 'No reviews yet. Five is where Google starts taking a local business seriously.'}</div>
    <div style="margin-top:.6rem">
      <a class="btn" href="https://g.page/r/CbTS5cA_a6nhEBM/review">Open the review form</a>
    </div></td></tr>`;

const thankRows = toThank.length ? toThank.map(({m,d}) =>
  `<tr><td>${esc(m.name)}<div class="sub">${esc(fmt(d,{day:'numeric',month:'short'}))}</div></td>
   <td class="r"><form method="POST" action="/webhook/ask-review" style="margin:0">
     <input type="hidden" name="meetingId" value="${esc(m.id)}">
     <button class="btn" type="submit">Ask for a review</button>
   </form></td></tr>`).join('')
  : '<tr><td colspan="2" class="quiet">Nobody waiting to be asked.</td></tr>';

const todayRows = today.length ? today.map(({m,d}) => {
  const join = joinOf(m);
  return `<tr><td class="t">${esc(fmt(d,{hour:'2-digit',minute:'2-digit'}))}</td>
    <td>${esc(m.name)}<div class="sub">${esc(m.status)}</div></td>
    <td class="r">${join ? `<a class="btn" href="${esc(join)}">Join</a>` : ''}</td></tr>`;
}).join('') : '<tr><td colspan="3" class="quiet">Nothing today.</td></tr>';

const soonRows = soon.length ? soon.map(({m,d}) =>
  `<tr><td class="t">${esc(fmt(d,{weekday:'short',day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}))}</td>
   <td>${esc(m.name)}</td><td class="r quiet">${esc(m.status)}</td></tr>`).join('')
  : '<tr><td colspan="3" class="quiet">Nothing booked.</td></tr>';

const needRows = unpaid.length ? unpaid.map(i =>
  `<tr><td>${esc(i.InvoiceNumber)}</td><td>${esc(i.Contact && i.Contact.Name)}</td>
   <td class="r">${money(i.AmountDue)}</td></tr>`).join('')
  : '<tr><td colspan="3" class="quiet">Nobody owes you anything.</td></tr>';

const html = `<!doctype html><html lang="en"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="robots" content="noindex">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link href="https://fonts.googleapis.com/css2?family=Poppins:wght@600&display=swap" rel="stylesheet">
<title>IT Surgery — Dashboard</title>
<style>
 :root{--brand:#990000;--ink:#333;--strong:#222;--quiet:#5a6068;--line:#dcdfe3;--bg:#f4f5f7}
 *{box-sizing:border-box}
 body{margin:0;background:var(--bg);color:var(--ink);
   font:14px/1.45 -apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif}
 header{background:#fff;border-bottom:3px solid var(--brand);padding:.85rem 1.25rem;
   display:flex;align-items:center;gap:.9rem;flex-wrap:wrap}
 header img{height:34px}
 .tabs{display:flex;gap:1.1rem;align-items:center}
 .tabs a{color:var(--brand);font-weight:600;text-decoration:none;font-size:.9rem;padding-bottom:.2rem}
 .tabs a.on{color:var(--strong);border-bottom:2px solid var(--brand)}
 header .when{margin-left:auto;color:var(--quiet);font-size:.85rem}
 main{padding:1rem 1.25rem;max-width:1780px;margin:0 auto}
 @media(min-width:1100px){body{zoom:.75}main{max-width:2400px}}
 h2{font-family:Poppins,sans-serif;font-weight:600;color:var(--strong);
   margin:0 0 .75rem;font-size:.95rem}
 .grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(270px,1fr));gap:1rem}
 .card{background:#fff;border:1px solid var(--line);border-radius:10px;padding:1rem}
 .figs{display:flex;gap:1.5rem;flex-wrap:wrap}
 .fig strong{display:block;font-family:Poppins,sans-serif;font-size:1.6rem;
   line-height:1.2;color:var(--strong)}
 .fig span{font-size:.78rem;color:var(--quiet)}
 table{width:100%;border-collapse:collapse}
 td{padding:.5rem 0;border-bottom:1px solid var(--line);font-size:.92rem;vertical-align:top}
 tr:last-child td{border-bottom:0}
 td.t{white-space:nowrap;color:var(--strong);font-weight:600;width:1%;padding-right:.9rem}
 td.r{text-align:right;white-space:nowrap}
 .sub{font-size:.78rem;color:var(--quiet)}
 .quiet{color:var(--quiet)}
 .stars{color:var(--brand);letter-spacing:.08em;margin-right:.4rem}
 .btn{display:inline-block;background:var(--brand);color:#fff;text-decoration:none;
   padding:.35rem .8rem;border-radius:6px;font-size:.82rem;margin-right:.4rem}
 .btn.ghost{background:#fff;color:var(--brand);border:1px solid var(--brand)}
 button.btn{border:0;cursor:pointer;font:inherit;font-size:.82rem}
 .job label{display:block;font-size:.78rem;color:var(--quiet);margin-bottom:.6rem}
 .job input,.job select{display:block;width:100%;margin-top:.2rem;padding:.45rem;
   border:1px solid var(--line);border-radius:6px;font:inherit;font-size:.92rem;color:var(--ink)}
 .job .row{display:flex;gap:.75rem}
 .job .row label{flex:1}
 .dot{display:inline-block;width:.6rem;height:.6rem;border-radius:50%;margin-right:.45rem}
 .dot.ok{background:#0b6e4f}.dot.bad{background:var(--brand)}.dot.busy{background:#b8860b}
 .health div{padding:.35rem 0;font-size:.9rem}
 @media(max-width:520px){header img{height:28px}}
</style></head><body>
<header>
  <img src="https://itsurgery.me/assets/logo.png" alt="IT Surgery">
  <nav class="tabs"><a class="on" href="/">Dashboard</a><a href="/monitoring">Monitoring</a><a href="/webmin-frame">Webmin</a></nav>
  <span class="when">${esc(fmt(now,{weekday:'long',day:'numeric',month:'long',hour:'2-digit',minute:'2-digit'}))}</span>
</header>
<main>
  <div class="card" style="margin-bottom:1rem">
    <h2>Money this month</h2>
    <div class="figs">
      <div class="fig"><strong>${money(invoiced)}</strong><span>invoiced</span></div>
      <div class="fig"><strong>${money(paid)}</strong><span>paid</span></div>
      <div class="fig"><strong>${money(owed)}</strong><span>outstanding</span></div>
      <div class="fig"><strong>${money(available)}</strong><span>in Stripe</span></div>
      <div class="fig"><strong>${rating ? rating.toFixed(1) : '—'}</strong>
        <span>${ratingCount ? ratingCount + ' Google review' + (ratingCount === 1 ? '' : 's') : 'no reviews yet'}</span></div>
      <div class="fig"><strong>${customerTotal}</strong><span>customers</span></div>
      <div class="fig"><strong>${openLeads.length}</strong><span>open enquiries</span></div>
      <div class="fig"><strong>${payout ? money(payout.amount/100) : '—'}</strong>
        <span>${payout ? 'next payout ' + esc(fmt(new Date(payout.arrival_date*1000),{day:'numeric',month:'short'})) : 'no payout scheduled'}</span></div>
    </div>
  </div>

  <div class="grid">
    <div class="card"><h2>Today</h2><table>${todayRows}</table></div>
    <div class="card"><h2>Needs you — unpaid</h2><table>${needRows}</table></div>
    <div class="card"><h2>New enquiries</h2><table>${leadRows}</table></div>
    <div class="card"><h2>Google reviews</h2><table>${reviewRows}</table></div>
    <div class="card"><h2>Ask for a review</h2><table>${thankRows}</table></div>
    <div class="card"><h2>New job</h2>
      <form method="POST" action="/webhook/custom-job" class="job">
        <label>Customer<input name="customer" required autocomplete="off"></label>
        <label>Their email<input name="email" type="email" required autocomplete="off"></label>
        <label>Work done<input name="work" required autocomplete="off"
          placeholder="Laptop screen replaced"></label>
        <div class="row">
          <label>Amount £<input name="amount" type="number" step="0.01" min="1" required></label>
          <label>VAT<select name="vat">
            <option value="home">Included (home)</option>
            <option value="business">Add VAT (business)</option>
          </select></label>
        </div>
        <button class="btn" type="submit">Raise invoice and send</button>
      </form>
    </div>
    <div class="card"><h2>Coming up</h2><table>${soonRows}</table></div>
    <div class="card health"><h2>Health</h2>
      <div>${dot(up('Website up?'))} itsurgery.me</div>
      <div>${dot(up('CRM up?'))} CRM</div>
      <div>${dot(up('Remote help up?'))} Remote help</div>
      <div>${dot(deployState)} Last deploy${deployState === 'running' ? ' — running' : ''}${
        deployRun ? ' — ' + esc(String(deployRun.display_title || '').slice(0,40)) : ''}</div>
    </div>
  </div>
</main></body></html>`;

return [{ json: { html } }];
